"""TEMPORARY diagnostic plugin: find who loads bare `ai_agent_bridge` (#6812 flake).

xdist workers each run this plugin; findings are appended to _bridge_trap.log
because pytest output capture would swallow prints from passing tests.
"""

import os
import sys
import traceback

_LOG = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_bridge_trap.log")
_ALREADY = "ai_agent_bridge" in sys.modules


def _log(msg):
    with open(_LOG, "a", encoding="utf-8") as fh:
        fh.write(f"[pid={os.getpid()}] {msg}\n")


class _Trap:
    def find_module(self, fullname, path=None):
        if fullname == "ai_agent_bridge" and fullname not in sys.modules:
            stack = "".join(traceback.format_stack(limit=40))
            _log(f"IMPORT-TRAP {fullname}\n{stack}\n-----")
        return None


if not _ALREADY:
    sys.meta_path.insert(0, _Trap())
else:
    _log(f"PRESENT-AT-STARTUP file={getattr(sys.modules['ai_agent_bridge'], '__file__', None)}")


def pytest_runtest_teardown(item, nextitem):
    if "ai_agent_bridge" in sys.modules and not getattr(item.session, "_bridge_seen", False):
        item.session._bridge_seen = True
        mod = sys.modules["ai_agent_bridge"]
        _log(f"FIRST-SEEN-AFTER {item.nodeid} file={getattr(mod, '__file__', None)}")


def pytest_sessionfinish(session, exitstatus):
    if "ai_agent_bridge" in sys.modules:
        mod = sys.modules["ai_agent_bridge"]
        _log(f"SESSION-END loaded file={getattr(mod, '__file__', None)}")

